INSERT INTO public.gallery_locations (slug, name, blurb, sort_order) VALUES ('masai-mara', 'Masai Mara', 'Kenya''s most celebrated reserve — endless golden plains, resident lion prides and the thundering Great Migration of wildebeest crossing from the Serengeti. Every photograph below was taken on one of our own safaris.', 0);
